-- Generated by scripts/build_compiled.py from src/fraudrules/rules/account-takeover/at-001-reset-new-device-payee.yaml. Do not edit.
-- AT-001 Credential reset, then a login from a new device, then a new payee
SELECT DISTINCT 'AT-001' AS rule_id, 'events' AS anchor_table, s2.id AS anchor_id
FROM events AS s2
JOIN events AS s1 ON s1.customer_id = s2.customer_id AND s1.ts < s2.ts AND (s1.event_type = 'login' AND s1.outcome = 'success' AND s1.device_new = 1)
JOIN events AS s0 ON s0.customer_id = s2.customer_id AND s0.ts < s1.ts AND s0.ts > s2.ts - 86400 AND (s0.event_type IN ('password_reset', 'mfa_change') AND s0.outcome = 'success')
WHERE (s2.event_type IN ('payee_added', 'payee_changed') AND s2.outcome = 'success');
